steps.script:
(() => {
  if (window.__loginSuccess) return true;

  const allClicks = Array.from(document.querySelectorAll(
    'a, button, input[type=button], input[type=submit], div[role=button], span[role=button], div[onclick], span[onclick], div.btn, span.btn, .back, .return'
  ));
  const backBtn = allClicks.find(el => {
    const text = (el.innerText || el.value || el.getAttribute('aria-label') || el.title || '').replace(/\s+/g, '').toLowerCase();
    return /返回|后退|back|<<|重试|重新登录|再次登录|重新认证/i.test(text);
  });
  if (backBtn) {
    backBtn.click();
  } else {
    const loginUrl = window.__authState && window.__authState.url;
    loginUrl ? (location.href = loginUrl) : location.reload();
  }

  return new Promise((resolve) => {
    const maxWait = 10000;
    const start = Date.now();
    const check = () => {
      const visInputs = Array.from(document.querySelectorAll('input:not([type=hidden]), textarea')).filter(el => {
        const s = getComputedStyle(el);
        if (!s || s.display === 'none' || s.visibility === 'hidden') return false;
        const r = el.getBoundingClientRect();
        return r.width > 2 && r.height > 2 && !el.disabled && !el.readOnly;
      });
      if (visInputs.length > 0) {
        resolve(true);
        return;
      }
      if (Date.now() - start > maxWait) {
        resolve(true);
        return;
      }
      setTimeout(check, 200);
    };
    check();
  });
})()

(() => {
  if (window.__loginSuccess) return true;
  return new Promise((resolve) => {
    const maxWait = 5000;
    const start = Date.now();
    const okWords = ['登录成功','认证成功','已连接','已上线','已认证','欢迎','在线','success','connected','welcome','online','logout','注销','退出登录','断开'];
    const failWords = ['密码错误','密码不正确','密码有误','密码过期','账号错误','账号不存在','账号已欠费','账号已停机','账号被禁用','账号或密码','用户名或密码','用户不存在','认证失败','登录失败','登入失败','操作失败','请重新登录','error','failed','invalid','incorrect','disabled','expired','suspended','forbidden'];
    const check = () => {
      const t = (document.body.innerText + ' ' + document.title).toLowerCase();
      if (okWords.some(w => t.includes(w.toLowerCase())) || document.querySelector('.alert-success,.msg-success,[class*=success],[class*=ok]')) {
        resolve(true);
        return;
      }
      if (failWords.some(w => t.includes(w.toLowerCase()))) {
        resolve(true);
        return;
      }
      if (Date.now() - start > maxWait) {
        resolve(true);
        return;
      }
      setTimeout(check, 300);
    };
    check();
  });
})()
